reference_solution:
def sum_subarray_minimums(nums):
    stack = []; total = ending = 0
    for value in nums:
        count = 1
        while stack and stack[-1][0] >= value:
            old, old_count = stack.pop(); count += old_count; ending -= old * old_count
        stack.append((value,count)); ending += value * count; total += ending
    return total

